/**
 * Signs Android release builds with a real upload key when one is available.
 *
 * Expo's template signs release builds with `debug.keystore` — the well-known
 * Android debug key that every machine shares. That is fine for installing on
 * your own phone and unacceptable for anything published: the key is public, so
 * anyone can sign an APK with it and Android will accept the result as a
 * legitimate update to Noto.
 *
 * `apps/mobile/android` is regenerated by `expo prebuild`, so this cannot be a
 * hand-edit of `app/build.gradle` — it has to be reapplied on every generation,
 * which is what a config plugin is for.
 *
 * The release workflow decodes the keystore from `ANDROID_KEYSTORE_BASE64` and
 * passes it through the environment variables below. When they are absent — any
 * local build — the debug keystore is used exactly as before.
 */

const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = 'NOTO_UPLOAD_STORE_FILE';

const UPLOAD_SIGNING_CONFIG = `
        upload {
            // Supplied by the release workflow from repository secrets. Absent
            // locally, which is why every use of this config is guarded.
            def uploadStoreFile = System.getenv("NOTO_UPLOAD_STORE_FILE")
            if (uploadStoreFile) {
                storeFile file(uploadStoreFile)
                storePassword System.getenv("NOTO_UPLOAD_STORE_PASSWORD")
                keyAlias System.getenv("NOTO_UPLOAD_KEY_ALIAS")
                keyPassword System.getenv("NOTO_UPLOAD_KEY_PASSWORD")
            }
        }
`;

const RELEASE_SIGNING_CONFIG = `            // A published build must not carry the shared debug key.
            signingConfig System.getenv("NOTO_UPLOAD_STORE_FILE") ? signingConfigs.upload : signingConfigs.debug`;

/**
 * Rewrites the `release` build type's signing configuration.
 *
 * Anchored on the `release { ... }` block rather than on the assignment alone,
 * because the `debug` build type contains a byte-identical line.
 */
function useUploadKeyForRelease(contents) {
  const releaseBlock = /(\n\s*release\s*\{)([\s\S]*?)(\n\s*\})/;

  const match = contents.match(releaseBlock);
  if (!match) return null;

  const body = match[2];
  const assignment = /\n[^\n]*signingConfig\s+signingConfigs\.debug/;
  if (!assignment.test(body)) return null;

  const rewritten = body.replace(assignment, `\n${RELEASE_SIGNING_CONFIG}`);
  return contents.replace(releaseBlock, `$1${rewritten}$3`);
}

function addUploadSigningConfig(contents) {
  const block = /(\n\s*signingConfigs\s*\{\n)/;
  if (!block.test(contents)) return null;
  return contents.replace(block, `$1${UPLOAD_SIGNING_CONFIG}`);
}

module.exports = function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (gradleConfig) => {
    const { modResults } = gradleConfig;

    if (modResults.language !== 'groovy') {
      throw new Error(
        `with-android-release-signing expects a Groovy build.gradle, found ${modResults.language}.`,
      );
    }

    // Prebuild can run against an already-generated project.
    if (modResults.contents.includes(MARKER)) return gradleConfig;

    const withConfig = addUploadSigningConfig(modResults.contents);
    if (!withConfig) {
      throw new Error(
        'with-android-release-signing could not find the signingConfigs block in app/build.gradle.',
      );
    }

    const withRelease = useUploadKeyForRelease(withConfig);
    if (!withRelease) {
      // Failing here is deliberate. Carrying on would produce a release build
      // signed with the public debug key and say nothing about it.
      throw new Error(
        'with-android-release-signing could not find the release signing configuration in app/build.gradle.',
      );
    }

    modResults.contents = withRelease;
    return gradleConfig;
  });
};
